struct HuffmanNode {
    char data;
    int freq;
    HuffmanNode *left, *right;

    HuffmanNode(char data, int freq) : data(data), freq(freq), left(nullptr), right(nullptr) {}
};

struct Compare {
    bool operator()(HuffmanNode* l, HuffmanNode* r) {
        return l->freq > r->freq;
    }
};

class HuffmanCoding {
public:
    unordered_map<char, string> encode(const string& text) {
        // Calculate frequencies
        unordered_map<char, int> freq;
        for (char c : text) freq[c]++;

        // Create priority queue
        priority_queue<HuffmanNode*, vector<HuffmanNode*>, Compare> pq;
        for (auto& p : freq) {
            pq.push(new HuffmanNode(p.first, p.second));
        }

        // Build Huffman tree
        while (pq.size() > 1) {
            HuffmanNode* left = pq.top(); pq.pop();
            HuffmanNode* right = pq.top(); pq.pop();

            HuffmanNode* parent = new HuffmanNode('$', left->freq + right->freq);
            parent->left = left;
            parent->right = right;
            pq.push(parent);
        }

        // Generate codes
        unordered_map<char, string> codes;
        generateCodes(pq.top(), "", codes);
        return codes;
    }

private:
    void generateCodes(HuffmanNode* root, string code, unordered_map<char, string>& codes) {
        if (!root) return;
        if (root->data != '$') codes[root->data] = code;
        generateCodes(root->left, code + "0", codes);
        generateCodes(root->right, code + "1", codes);
    }
};

function activitySelection(start, finish) {
    // Activities sorted by finish time
    const activities = start.map((s, i) => ({ start: s, finish: finish[i], index: i }));
    activities.sort((a, b) => a.finish - b.finish);

    const selected = [activities[0].index];
    let lastFinish = activities[0].finish;

    for (let i = 1; i < activities.length; i++) {
        if (activities[i].start >= lastFinish) {
            selected.push(activities[i].index);
            lastFinish = activities[i].finish;
        }
    }

    return selected;
}

class UnionFind {
    constructor(size) {
        this.parent = Array.from({ length: size }, (_, i) => i);
        this.rank = Array(size).fill(0);
    }

    find(x) {
        if (this.parent[x] !== x) {
            this.parent[x] = this.find(this.parent[x]); // Path compression
        }
        return this.parent[x];
    }

    union(x, y) {
        const rootX = this.find(x);
        const rootY = this.find(y);

        if (rootX === rootY) return false;

        // Union by rank
        if (this.rank[rootX] < this.rank[rootY]) {
            this.parent[rootX] = rootY;
        } else if (this.rank[rootX] > this.rank[rootY]) {
            this.parent[rootY] = rootX;
        } else {
            this.parent[rootY] = rootX;
            this.rank[rootX]++;
        }
        return true;
    }
}

function kruskalMST(n, edges) {
    // Sort edges by weight
    edges.sort((a, b) => a[2] - b[2]);

    const uf = new UnionFind(n);
    const mst = [];
    let totalWeight = 0;

    for (const [u, v, weight] of edges) {
        if (uf.union(u, v)) {
            mst.push([u, v, weight]);
            totalWeight += weight;
        }
    }

    return { mst, totalWeight };
}

public class TarjanSCC {
    private int time = 0;
    private List<List<Integer>> sccs = new ArrayList<>();

    public List<List<Integer>> findSCCs(Map<Integer, List<Integer>> graph, int n) {
        int[] disc = new int[n];
        int[] low = new int[n];
        boolean[] onStack = new boolean[n];
        Stack<Integer> stack = new Stack<>();
        Arrays.fill(disc, -1);

        for (int i = 0; i < n; i++) {
            if (disc[i] == -1) {
                dfs(i, graph, disc, low, onStack, stack);
            }
        }

        return sccs;
    }

    private void dfs(int u, Map<Integer, List<Integer>> graph, int[] disc, 
                     int[] low, boolean[] onStack, Stack<Integer> stack) {
        disc[u] = low[u] = time++;
        stack.push(u);
        onStack[u] = true;

        for (int v : graph.getOrDefault(u, new ArrayList<>())) {
            if (disc[v] == -1) {
                dfs(v, graph, disc, low, onStack, stack);
                low[u] = Math.min(low[u], low[v]);
            } else if (onStack[v]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }

        if (low[u] == disc[u]) {
            List<Integer> scc = new ArrayList<>();
            int v;
            do {
                v = stack.pop();
                onStack[v] = false;
                scc.add(v);
            } while (v != u);
            sccs.add(scc);
        }
    }
}

def matrix_chain_multiplication(dimensions):
    """
    Find minimum number of scalar multiplications for matrix chain
    dimensions: array where matrix i has dimensions[i-1] x dimensions[i]
    """
    n = len(dimensions) - 1
    dp = [[0] * n for _ in range(n)]
    split = [[0] * n for _ in range(n)]

    # l is chain length
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            dp[i][j] = float('inf')

            for k in range(i, j):
                cost = (dp[i][k] + dp[k + 1][j] + 
                       dimensions[i] * dimensions[k + 1] * dimensions[j + 1])
                if cost < dp[i][j]:
                    dp[i][j] = cost
                    split[i][j] = k

    def get_parenthesization(i, j):
        if i == j:
            return f"M{i}"
        k = split[i][j]
        return f"({get_parenthesization(i, k)} x {get_parenthesization(k + 1, j)})"

    return dp[0][n - 1], get_parenthesization(0, n - 1)

