class TravelingSalesman {
public:
    int tsp(vector<vector<int>>& dist) {
        int n = dist.size();
        vector<vector<int>> dp(1 << n, vector<int>(n, INT_MAX));

        // Start from city 0
        dp[1][0] = 0;

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int u = 0; u < n; u++) {
                if (!(mask & (1 << u))) continue;
                if (dp[mask][u] == INT_MAX) continue;

                for (int v = 0; v < n; v++) {
                    if (mask & (1 << v)) continue;

                    int newMask = mask | (1 << v);
                    dp[newMask][v] = min(dp[newMask][v], 
                                        dp[mask][u] + dist[u][v]);
                }
            }
        }

        // Find minimum cost to return to start
        int fullMask = (1 << n) - 1;
        int result = INT_MAX;
        for (int u = 1; u < n; u++) {
            if (dp[fullMask][u] != INT_MAX) {
                result = min(result, dp[fullMask][u] + dist[u][0]);
            }
        }

        return result;
    }
};

function boyerMoore(text, pattern) {
    const m = pattern.length;
    const n = text.length;

    // Bad character heuristic
    const badChar = new Map();
    for (let i = 0; i < m; i++) {
        badChar.set(pattern[i], i);
    }

    const matches = [];
    let s = 0; // shift of pattern with respect to text

    while (s <= n - m) {
        let j = m - 1;

        // Keep reducing j while characters match
        while (j >= 0 && pattern[j] === text[s + j]) {
            j--;
        }

        if (j < 0) {
            // Pattern found
            matches.push(s);
            s += (s + m < n) ? m - (badChar.get(text[s + m]) || -1) : 1;
        } else {
            // Shift pattern
            s += Math.max(1, j - (badChar.get(text[s + j]) || -1));
        }
    }

    return matches;
}

def convex_hull_graham_scan(points):
    """
    Graham scan algorithm for convex hull
    Returns points in counter-clockwise order
    """
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Sort points lexicographically
    points = sorted(set(points))

    if len(points) <= 1:
        return points

    # Build lower hull
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # Build upper hull
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Remove last point of each half because it's repeated
    return lower[:-1] + upper[:-1]

public class SuffixArray {
    public int[] buildSuffixArray(String s) {
        int n = s.length();
        Integer[] suffixes = new Integer[n];
        for (int i = 0; i < n; i++) suffixes[i] = i;

        // Sort suffixes using first character, then first 2, 4, 8, ...
        int[] rank = new int[n];
        int[] tempRank = new int[n];

        for (int i = 0; i < n; i++) {
            rank[i] = s.charAt(i);
        }

        for (int k = 1; k < n; k *= 2) {
            final int gap = k;
            final int[] finalRank = rank.clone();

            Arrays.sort(suffixes, (a, b) -> {
                if (finalRank[a] != finalRank[b]) {
                    return finalRank[a] - finalRank[b];
                }
                int rankA = (a + gap < n) ? finalRank[a + gap] : -1;
                int rankB = (b + gap < n) ? finalRank[b + gap] : -1;
                return rankA - rankB;
            });

            tempRank[suffixes[0]] = 0;
            for (int i = 1; i < n; i++) {
                int prev = suffixes[i - 1];
                int curr = suffixes[i];
                tempRank[curr] = tempRank[prev];

                if (finalRank[curr] != finalRank[prev]) {
                    tempRank[curr]++;
                } else {
                    int rankPrev = (prev + gap < n) ? finalRank[prev + gap] : -1;
                    int rankCurr = (curr + gap < n) ? finalRank[curr + gap] : -1;
                    if (rankPrev != rankCurr) {
                        tempRank[curr]++;
                    }
                }
            }
            rank = tempRank.clone();
        }

        return Arrays.stream(suffixes).mapToInt(Integer::intValue).toArray();
    }
}

